feature-rle.solution.py:
def rle(text):
    result=[]
    for c in text:
        if result and result[-1][0]==c: result[-1][1]+=1
        else: result.append([c,1])
    return result

feature-flatten.solution.py:
def flatten(values):
    result=[]
    for v in values:
        result.extend(flatten(v)) if isinstance(v,list) else result.append(v)
    return result

