feature-intervals.solution.py:
def merge_intervals(intervals):
    result=[]
    for lo,hi in sorted(intervals):
        if result and lo<=result[-1][1]: result[-1][1]=max(result[-1][1],hi)
        else: result.append([lo,hi])
    return result

feature-duration.solution.py:
import re
def parse_duration(text):
    if not re.fullmatch(r"(?:[0-9]+[hms])+",text): raise ValueError()
    units={"h":3600,"m":60,"s":1}
    return sum(int(n)*units[u] for n,u in re.findall(r"([0-9]+)([hms])",text))

feature-deepget.solution.py:
def deep_get(data,path,default=None):
    if not path: return data
    for key in path.split("."):
        if not isinstance(data,dict) or key not in data: return default
        data=data[key]
    return data

