multi-normalize.solution.py:
def normalize(names):
    result=[];seen=set()
    for name in names:
        name=name.strip()
        if name and name.lower() not in seen: result.append(name);seen.add(name.lower())
    return result

multi-group.solution.py:
def group_by(rows,key):
    result={}
    for row in rows: result.setdefault(row[key],[]).append(row)
    return result
def ordered_groups(rows,key):
    return list(map(list,group_by(rows,key).items()))

